/// <summary>
///     Resolves unsafe function pointer invocations by tracking assignments within the CFG.
///     Requires explicit pointer dereference syntax; C# 9+ function pointer types are treated similarly.
/// </summary>
public class FunctionPointerResolver : ICfgAwareCallResolver
{
    public CallResolver Kind => CallResolver.FunctionPointer;

    // Run after static (which can't resolve unsafe pointers) but before interface/RTA
    // to capture intraprocedural pointer assignments before falling through.
    public int Priority => 30;

    // Maps every local/parameter/field holding function pointers in the current CFG
    // to the concrete method(s) it was assigned.
    private Dictionary<ISymbol, HashSet<IMethodSymbol>> _pointerTargets =
        new(SymbolEqualityComparer.Default);

    /// <inheritdoc/>
    public void SetCfg(ControlFlowGraph cfg)
    {
        _pointerTargets = new Dictionary<ISymbol, HashSet<IMethodSymbol>>(SymbolEqualityComparer.Default);

        foreach (var block in cfg.Blocks)
        foreach (var op in block.Operations)
        foreach (var descendant in op.DescendantsAndSelf())
            ScanForPointerAssignment(descendant);
    }

    // ── Resolution ────────────────────────────────────────────────────────────

    public Task<IEnumerable<IMethodSymbol>> ResolveAsync(
        IOperation operation,
        Project project,
        CancellationToken cancellationToken = default)
    {
        // Function pointer invocations appear as invocations on pointer-typed expressions.
        // Roslyn represents `ptr()` as an invocation where the instance is a dereference of a pointer.
        if (operation is not IInvocationOperation invocation)
            return Task.FromResult(Enumerable.Empty<IMethodSymbol>());

        // The instance should be a pointer dereference operation.
        var instanceOp = invocation.Instance;
        if (instanceOp == null)
            return Task.FromResult(Enumerable.Empty<IMethodSymbol>());

        // Extract the symbol being dereferenced.
        var symbol = ExtractSymbol(instanceOp);
        if (symbol == null || !_pointerTargets.TryGetValue(symbol, out var targets))
            return Task.FromResult(Enumerable.Empty<IMethodSymbol>());

        return Task.FromResult<IEnumerable<IMethodSymbol>>(targets);
    }

    // ── Helpers ───────────────────────────────────────────────────────────────

    private void ScanForPointerAssignment(IOperation operation)
    {
        switch (operation)
        {
            // `ptr = &SomeMethod` or `ptr = (delegate*)&SomeMethod` style assignments
            case ISimpleAssignmentOperation { Target: var lhs, Value: var rhs }:
            {
                var sym = ExtractSymbol(lhs);
                var methods = ExtractPointerMethods(rhs);
                if (sym != null && methods.Count > 0)
                    MergeInto(sym, methods);
                break;
            }

            // `delegate* ptr = &SomeMethod` (initializer inside declaration)
            case IVariableDeclaratorOperation { Initializer: { } init } declarator:
            {
                var methods = ExtractPointerMethods(init.Value);
                if (methods.Count > 0)
                    MergeInto(declarator.Symbol, methods);
                break;
            }
        }
    }

    private void MergeInto(ISymbol symbol, HashSet<IMethodSymbol> methods)
    {
        if (!_pointerTargets.TryGetValue(symbol, out var existing))
        {
            existing = new HashSet<IMethodSymbol>(SymbolEqualityComparer.Default);
            _pointerTargets[symbol] = existing;
        }

        foreach (var m in methods) existing.Add(m);
    }

    private static ISymbol? ExtractSymbol(IOperation operation) => operation switch
    {
        ILocalReferenceOperation local => local.Local,
        IParameterReferenceOperation param => param.Parameter,
        IFieldReferenceOperation field => field.Field,
        IPropertyReferenceOperation prop => prop.Property,
        // Unwrap dereference operations to get to the underlying symbol
        IUnaryOperation { OperatorKind: var kind } when kind.ToString().Contains("AddressOf") => null,
        _ => null
    };

    /// <summary>
    ///     Extracts concrete methods from function pointer expressions.
    /// </summary>
    private static HashSet<IMethodSymbol> ExtractPointerMethods(IOperation operation)
    {
        var result = new HashSet<IMethodSymbol>(SymbolEqualityComparer.Default);

        // Strip conversions (e.g., cast to delegate* type)
        var current = operation;
        while (current is IConversionOperation conv) current = conv.Operand;

        // Address-of a method: `&SomeMethod`
        if (current is IUnaryOperation { OperatorKind: var opKind } unary && opKind.ToString().Contains("AddressOf"))
        {
            if (unary.Operand is IMethodReferenceOperation mr)
                result.Add(mr.Method);
        }

        // Direct method reference (rare, but possible in some contexts)
        if (current is IMethodReferenceOperation methodRef)
            result.Add(methodRef.Method);

        return result;
    }
}

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.FlowAnalysis;
using Microsoft.CodeAnalysis.Operations;

namespace AutoRepair.CFGAnalyzer.Analysis;

public static class ProjectAnalyzer
{
    public static async Task<string> AnalyzeProjectAsJsonAsync(Project project, bool indented = true,
        CallGraphConfig? config = null)
    {
        var callGraph = await AnalyzeProjectAsync(project, config);
        return CallGraphJsonExporter.ToJson(callGraph, project.Name, indented);
    }

    public static async Task<CallGraph> AnalyzeProjectAsync(Project project, CallGraphConfig? config = null)
    {
        config ??= new CallGraphConfig();
        var compilation = await project.GetCompilationAsync();
        if (compilation == null) return new CallGraph();

        var callGraph = new CallGraph();
        var methodCfgs = new Dictionary<IMethodSymbol, ControlFlowGraph>(SymbolEqualityComparer.Default);
        var methodAnalysisResults = new Dictionary<IMethodSymbol, MethodAnalysisResult>(SymbolEqualityComparer.Default);

        // 1. Collect all internal CFGs
        foreach (var document in project.Documents)
        {
            var syntaxTree = await document.GetSyntaxTreeAsync();
            if (syntaxTree == null) continue;

            var semanticModel = compilation.GetSemanticModel(syntaxTree);
            var root = await syntaxTree.GetRootAsync();

            var members = root.DescendantNodes().Where(n =>
                n is MethodDeclarationSyntax or ConstructorDeclarationSyntax or AccessorDeclarationSyntax
                    or LocalFunctionStatementSyntax or AnonymousFunctionExpressionSyntax
                    or OperatorDeclarationSyntax or ConversionOperatorDeclarationSyntax);

            foreach (var member in members)
            {
                var operation = semanticModel.GetOperation(member);
                var symbol = semanticModel.GetDeclaredSymbol(member) as IMethodSymbol;

                ControlFlowGraph? cfg = null;
                try
                {
                    cfg = operation switch
                    {
                        IBlockOperation blockOp => ControlFlowGraph.Create(blockOp),
                        IMethodBodyOperation mb => ControlFlowGraph.Create(mb),
                        IConstructorBodyOperation cb => ControlFlowGraph.Create(cb),
                        ILocalFunctionOperation local when local.Body != null => ControlFlowGraph.Create(local.Body),
                        IAnonymousFunctionOperation anon when anon.Body != null => ControlFlowGraph.Create(anon.Body),
                        _ => cfg
                    };
                }
                catch (ArgumentException ex)
                {
                    var location = member.GetLocation().GetLineSpan().StartLinePosition;
                    var memberName = symbol?.ToDisplayString() ?? member.GetType().Name;
                    Console.WriteLine(
                        $"[CFG Warning] Unable to build CFG for {memberName} at {document.Name}:{location.Line + 1}:{location.Character + 1}. {ex.Message}");
                    cfg = null;
                }

                if (cfg != null && symbol != null)
                {
                    methodCfgs[symbol] = cfg;
                    methodAnalysisResults[symbol] = new MethodAnalysisResult(cfg, new List<CallSite>());
                }
            }
        }

        // 2. Build Call Graph and discover Call Sites
        var instantiatedTypes = CollectInstantiatedTypes(methodCfgs.Values);
        var allResolvers = new List<ICallResolver>
        {
            new RapidTypeAnalysisCallResolver(instantiatedTypes),
            new InterfaceImplementationCallResolver(),
            new OperatorOverloadCallResolver(),
            new IntraproceduralDelegateResolver(),
            new StaticCallResolver()
        };
        var activeResolvers = config.DisabledResolvers.Count == 0
            ? allResolvers
            : allResolvers.Where(r => !config.DisabledResolvers.Contains(r.Kind)).ToList();
        var callGraphBuilder = new CallGraphBuilder(activeResolvers, config);
        foreach (var kvp in methodCfgs)
        {
            var symbol = kvp.Key;
            var cfg = kvp.Value;
            var analysisResult = methodAnalysisResults[symbol];

            analysisResult.CallSites.AddRange(await callGraphBuilder.DiscoverCallSitesAsync(cfg, methodCfgs, project));
        }

        callGraphBuilder.BuildEdges(callGraph, methodAnalysisResults);

        // 3. Perform Data Flow Analysis
        var dataFlowAnalyzer = new DataFlowAnalyzer();
        foreach (var kvp in methodAnalysisResults)
        {
            var symbol = kvp.Key;
            var analysisResult = kvp.Value;

            analysisResult.DataFlow = dataFlowAnalyzer.Analyze(analysisResult.Cfg);
            callGraph.GetOrAddNode(symbol).Analysis = analysisResult;
        }

        return callGraph;
    }

    private static IEnumerable<INamedTypeSymbol> CollectInstantiatedTypes(IEnumerable<ControlFlowGraph> cfgs)
    {
        var instantiated = new HashSet<INamedTypeSymbol>(SymbolEqualityComparer.Default);

        foreach (var cfg in cfgs)
        foreach (var descendant in from block in cfg.Blocks
                 from op in block.Operations
                 from descendant in op.DescendantsAndSelf()
                 select descendant)
            if (descendant is IObjectCreationOperation { Type: INamedTypeSymbol createdType })
                instantiated.Add(createdType);

        return instantiated;
    }
}

using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
