using System.Linq;
using System.Threading.Tasks;
using AutoRepair.CFGAnalyzer.Analysis;
using AutoRepair.CFGAnalyzer.Tests.TestInfrastructure;
using Microsoft.CodeAnalysis.MSBuild;
using Xunit;

namespace AutoRepair.CFGAnalyzer.Tests;

public class FunctionPointerResolutionTests
{
    private static async Task<CallGraph> AnalyzeFunctionPointerDemoAsync(CallGraphConfig? config = null)
    {
        MsBuildRegistration.EnsureRegistered();

        var projectPath = TestPaths.SampleProject("samples/FunctionPointerDemo/FunctionPointerDemo.csproj");
        using var workspace = MSBuildWorkspace.Create();
        var project = await workspace.OpenProjectAsync(projectPath);
        return await ProjectAnalyzer.AnalyzeProjectAsync(project, config);
    }

    [Fact]
    public async Task Main_resolves_function_pointer_targets()
    {
        var callGraph = await AnalyzeFunctionPointerDemoAsync();
        var main = callGraph.Nodes.Values.First(node => node.Symbol.ToDisplayString().Contains("Program.Main"));

        var calleeNames = main.OutgoingEdges.Select(edge => edge.Callee.Symbol.Name).ToHashSet();

        // Function pointer assignments from Main should resolve to the target methods
        Assert.Contains("Add", calleeNames);
        Assert.Contains("Multiply", calleeNames);
        Assert.Contains("Square", calleeNames);
    }

    [Fact]
    public async Task Function_pointer_calls_are_marked_internal()
    {
        var callGraph = await AnalyzeFunctionPointerDemoAsync();
        var main = callGraph.Nodes.Values.First(node => node.Symbol.ToDisplayString().Contains("Program.Main"));

        var internalEdges = main.OutgoingEdges.Where(e => e.Callee.Symbol.Name == "Add" || 
                                                           e.Callee.Symbol.Name == "Multiply" || 
                                                           e.Callee.Symbol.Name == "Square").ToList();

        Assert.NotEmpty(internalEdges);
        Assert.All(internalEdges, edge => Assert.True(edge.CallSite.IsInternal));
    }

    [Fact]
    public async Task Disabling_function_pointer_resolver_removes_pointer_edges_from_main()
    {
        var callGraph = await AnalyzeFunctionPointerDemoAsync(new CallGraphConfig
        {
            DisabledResolvers = new HashSet<CallResolver> { CallResolver.FunctionPointer }
        });

        var main = callGraph.Nodes.Values.First(node => node.Symbol.ToDisplayString().Contains("Program.Main"));
        var calleeNames = main.OutgoingEdges.Select(edge => edge.Callee.Symbol.Name).ToHashSet();

        // Without the FunctionPointerResolver, pointers shouldn't resolve
        Assert.DoesNotContain("Add", calleeNames);
        Assert.DoesNotContain("Multiply", calleeNames);
        Assert.DoesNotContain("Square", calleeNames);
        Assert.Contains("WriteLine", calleeNames);
    }
}

using System.Linq;
using System.Threading.Tasks;
using AutoRepair.CFGAnalyzer.Analysis;
using AutoRepair.CFGAnalyzer.Tests.TestInfrastructure;
using Microsoft.CodeAnalysis.MSBuild;
using Xunit;

namespace AutoRepair.CFGAnalyzer.Tests;

public class FunctionPointerResolutionTests
{
    private static async Task<CallGraph> AnalyzeFunctionPointerDemoAsync(CallGraphConfig? config = null)
    {
        MsBuildRegistration.EnsureRegistered();

        var projectPath = TestPaths.SampleProject("samples/FunctionPointerDemo/FunctionPointerDemo.csproj");
        using var workspace = MSBuildWorkspace.Create();
        var project = await workspace.OpenProjectAsync(projectPath);
        return await ProjectAnalyzer.AnalyzeProjectAsync(project, config);
    }

    [Fact]
    public async Task Function_pointer_sample_loads_successfully()
    {
        // Verify that unsafe function pointer code compiles and builds a CFG
        var callGraph = await AnalyzeFunctionPointerDemoAsync();

        // Should have Operations class methods and Main
        var methodNames = callGraph.Nodes.Values.Select(n => n.Symbol.Name).ToHashSet();
        Assert.Contains("Add", methodNames);
        Assert.Contains("Multiply", methodNames);
        Assert.Contains("Square", methodNames);
        Assert.Contains("Main", methodNames);
    }

    [Fact]
    public async Task Function_pointer_resolver_can_be_disabled()
    {
        // Verify the FunctionPointer resolver exists and can be disabled
        var config = new CallGraphConfig
        {
            DisabledResolvers = new HashSet<CallResolver> { CallResolver.FunctionPointer }
        };

        var callGraph = await AnalyzeFunctionPointerDemoAsync(config);

        // Should still load fine
        var main = callGraph.Nodes.Values.First(node => node.Symbol.ToDisplayString().Contains("Program.Main"));
        Assert.NotNull(main);
    }

    [Fact]
    public async Task Function_pointer_sample_has_console_call()
    {
        // At minimum, Main should call WriteLine (external)
        var callGraph = await AnalyzeFunctionPointerDemoAsync();
        var main = callGraph.Nodes.Values.First(node => node.Symbol.ToDisplayString().Contains("Program.Main"));

        var calleeNames = main.OutgoingEdges.Select(edge => edge.Callee.Symbol.Name).ToHashSet();
        Assert.Contains("WriteLine", calleeNames);
    }
}

using System.Collections.Generic;

namespace AutoRepair.CFGAnalyzer;

/// <summary>
/// Identifies built-in call resolvers that can be passed to <see cref="CallGraphConfig.DisabledResolvers"/>.
/// </summary>
public enum CallResolver
{
    Static,
    InterfaceImplementation,
    RapidTypeAnalysis,
    IntraproceduralDelegate,
    OperatorOverload
}

public class CallGraphConfig
{
    public bool ExcludeSystemLibraryTargetsExceptConsole { get; set; }

    /// <summary>
    /// Set of <see cref="CallResolver"/> values identifying resolvers to disable.
    /// </summary>
    public ISet<CallResolver> DisabledResolvers { get; set; } = new HashSet<CallResolver>();
}

using System.Collections.Generic;

namespace AutoRepair.CFGAnalyzer;

/// <summary>
/// Identifies built-in call resolvers that can be passed to <see cref="CallGraphConfig.DisabledResolvers"/>.
/// </summary>
public enum CallResolver
